import {scannerDeviceToken} from './push.js?v=0.21.0';
import {imageCanvas} from './photo-tools.js?v=0.21.0';
const API='https://delivery-manager-reminders.tonykevinjr.workers.dev',KEY='delivery-manager-cloud-scan-v1';
let config=read();
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'null');}catch{return null;}}
export function cloudScanStatus(){return {enabled:!!config?.token,canReuseDevice:!!scannerDeviceToken()};}
export async function enableCloudScan(code=''){const token=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join(''),existing=scannerDeviceToken();const response=await fetch(API+'/scan/register',{method:'POST',headers:{'Content-Type':'application/json',...(existing?{Authorization:'Bearer '+existing}:{})},body:JSON.stringify({code,token}),cache:'no-store',signal:AbortSignal.timeout(15000)});const body=await response.json();if(!response.ok)throw Error(body.error||'Could not connect the scanner.');config={token};localStorage.setItem(KEY,JSON.stringify(config));}
export async function disableCloudScan(){const previous=config;config=null;localStorage.removeItem(KEY);if(previous?.token)await fetch(API+'/scan/disable',{method:'POST',headers:{Authorization:'Bearer '+previous.token},cache:'no-store',keepalive:true,signal:AbortSignal.timeout(10000)});}
export async function scanCloudTicket(file,{signal}={}){if(!config?.token)throw Error('Set up the in-app scanner first.');if(!navigator.onLine)throw Error('Ticket scanning needs an internet connection. You can still enter this order manually.');const canvas=await imageCanvas(file,2000);let image;try{image=await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Could not prepare this photo.')),'image/jpeg',.9));}finally{canvas.width=0;canvas.height=0;}if(image.size>2500000)throw Error('Photo is too large. Move closer to the customer information.');const abort=new AbortController(),cancel=()=>abort.abort(),timer=setTimeout(cancel,35000);signal?.addEventListener('abort',cancel,{once:true});if(signal?.aborted)cancel();try{const response=await fetch(API+'/scan',{method:'POST',headers:{'Content-Type':'image/jpeg',Authorization:'Bearer '+config.token},body:image,cache:'no-store',signal:abort.signal});const body=await response.json();if(response.status===401){config=null;localStorage.removeItem(KEY);}if(!response.ok)throw Error(body.error||'Could not read this ticket.');return body.fields;}catch(e){if(e.name==='AbortError'&&!signal?.aborted)throw Error('The scan took too long. Check the connection and try again.');throw e;}finally{clearTimeout(timer);signal?.removeEventListener('abort',cancel);image=null;}}

export const cloudScanToken=()=>config?.token||null;
